import { createClient as createClient3 } from "npm:@supabase/supabase-js@^2.118.0";
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.20.1";
import { z } from "npm:zod@^3.25.76";
function supabaseForUser3(ctx) {
  return createClient3(process.env.SUPABASE_URL, process.env.SUPABASE_PUBLISHABLE_KEY, {
    global: { headers: { Authorization: `Bearer ${ctx.getToken()}` } },
    auth: { persistSession: false, autoRefreshToken: false }
  });
}
var list_courses_default = defineTool3({
  name: "list_courses",
  title: "List available courses",
  description: "Lists courses available in the Coopaiba catalog (subject to the signed-in user's access).",
  inputSchema: {
    search: z.string().trim().optional().describe("Optional case-insensitive title filter."),
    limit: z.number().int().min(1).max(100).optional().describe("Max rows to return (default 50).")
  },
  annotations: { readOnlyHint: true, openWorldHint: false },
  handler: async ({ search, limit }, ctx) => {
    if (!ctx.isAuthenticated())
      return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    const supabase = supabaseForUser3(ctx);
    let q = supabase.from("courses").select("id, title, description, duration, is_paid, price, cooperado_only, eventual, created_at").order("created_at", { ascending: false }).limit(limit ?? 50);
    if (search) q = q.ilike("title", `%${search}%`);
    const { data, error } = await q;
    if (error)
      return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: JSON.stringify(data, null, 2) }],
      structuredContent: { courses: data ?? [] }
    };
  }
});

