import { createClient as createClient4 } from "npm:@supabase/supabase-js@^2.118.0";
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.20.1";
function supabaseForUser4(ctx) {
  return createClient4(process.env.SUPABASE_URL, process.env.SUPABASE_PUBLISHABLE_KEY, {
    global: { headers: { Authorization: `Bearer ${ctx.getToken()}` } },
    auth: { persistSession: false, autoRefreshToken: false }
  });
}
var get_my_profile_default = defineTool4({
  name: "get_my_profile",
  title: "Get my profile",
  description: "Returns the signed-in user's Coopaiba profile (name, cooperativa, role).",
  inputSchema: {},
  annotations: { readOnlyHint: true, openWorldHint: false },
  handler: async (_input, ctx) => {
    if (!ctx.isAuthenticated())
      return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    const supabase = supabaseForUser4(ctx);
    const uid = ctx.getUserId();
    const [profileRes, rolesRes] = await Promise.all([
      supabase.from("profiles").select("full_name, cooperativa, phone, avatar_url").eq("user_id", uid).maybeSingle(),
      supabase.from("user_roles").select("role").eq("user_id", uid)
    ]);
    if (profileRes.error)
      return { content: [{ type: "text", text: profileRes.error.message }], isError: true };
    const payload = {
      user_id: uid,
      email: ctx.getUserEmail(),
      profile: profileRes.data,
      roles: (rolesRes.data ?? []).map((r) => r.role)
    };
    return {
      content: [{ type: "text", text: JSON.stringify(payload, null, 2) }],
      structuredContent: payload
    };
  }
});

